const raw = $input.first().json['Songs'];
const songs = raw.split('\n').map(s => s.trim()).filter(s => s.length > 0);
if (songs.length === 0) throw new Error('No input provided!');
return songs.map((q, i) => ({ json: { query: q, index: i+1, total: songs.length } }));

const raw = $input.first().json.stdout;
let result;
try { result = JSON.parse(raw); }
catch(e) { return [{ json: { status:'parse_error', raw } }]; }
const prev = $('Split Input').item.json;
result.inputIndex = prev.index;
result.inputTotal = prev.total;
result.originalQuery = prev.query;
return [{ json: result }];
